```{=html}
<div id="language-switcher">
  <button id="lang-en" onclick="switchLanguage('en')" class="lang-btn active">🇬🇧 EN</button>
  <button id="lang-es" onclick="switchLanguage('es')" class="lang-btn">🇪🇸 ES</button>
</div>

<style>
#language-switcher {
  position: fixed;
  top: 20px;
  right: 20px;
  z-index: 1000;
  display: flex;
  gap: 8px;
  background: white;
  padding: 4px;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.lang-btn {
  background: white;
  border: 2px solid #ddd;
  padding: 8px 14px;
  cursor: pointer;
  border-radius: 6px;
  font-size: 14px;
  transition: all 0.3s ease;
  font-weight: normal;
  color: #333;
}

.lang-btn:hover {
  background: #f5f5f5;
  border-color: #999;
}

.lang-btn.active {
  background: #0066cc;
  color: white;
  border-color: #0066cc;
  font-weight: bold;
}
</style>

<script>
let currentLang = 'en';

function switchLanguage(lang) {
  currentLang = lang;
  document.querySelectorAll('[data-lang]').forEach(el => {
    if (el.getAttribute('data-lang') === lang) {
      el.style.display = '';
    } else {
      el.style.display = 'none';
    }
  });
  document.getElementById('lang-en').classList.toggle('active', lang === 'en');
  document.getElementById('lang-es').classList.toggle('active', lang === 'es');
}

document.addEventListener('DOMContentLoaded', function() {
  switchLanguage('en');
});
</script>
```

